@@ -554,7 +560,7 @@ class SpaceTracker {
       name,
       spaceButtonId,
       tabInSpace: tabInfo => (tabInfo.spaceButtonId == spaceButtonId ? 1 : 0),
-      defaultUrl,
+      tabProperties,
       buttonProperties,
       extension,
     });
